trace.sql:
WITH params AS (
  SELECT 0.9101902140804468 AS r, 2138 AS n
),
t AS (
  SELECT r, n, r*sqrt((n-2)*1.0/(1-r*r)) AS tstat, n-2 AS df FROM params
),
-- regularized incomplete beta I_x(a,b) via continued fraction
-- x = df/(df+t^2), a=df/2, b=0.5; p = I_x(a,b)
-- Use recursive series/continued fraction in pure SQL via a precomputed approach is hard;
-- Instead use the symmetry: I_x(a,b) = 1 - I_{1-x}(b,a). x near 1 so use 1-x = t^2/(df+t^2) small.
tvals AS (
  SELECT tstat, df, (tstat*tstat)/(df+tstat*tstat) AS y FROM t
)
SELECT tstat, df, y,
  /* betacf continued fraction for I_y(b=0.5, a=df/2) via Lentz */
  (1.0) AS placeholder
FROM tvals;

